#!/usr/bin/env bash
# corpse-los.sh — замер видимости ближайшего трупа (KUMM баг 64 п. 11, трупы): что луч подсветки выбрал, режим камеры, высоты камеры и глаз
# над телом и родная ConanCharacter:IsInteractableInLineOfSight для четырёх точек — тело + 10 см по взгляду камеры (так зовёт игра,
# UpdateHighlightTarget), + 10 см по взгляду от глаз, центр тела, центр + 20 см. Только чтение.
# [NOT-TESTED]
cd "$(dirname "$0")"
bash pult.sh "lua local p=FindFirstOf('BasePlayerChar_C'); local pc=FindFirstOf('FunCombat_PlayerController_C'); local hl=p:K2_GetActorLocation(); local best,bd; for _,a in ipairs(FindAllOf('Corpse_C') or {}) do if a:IsValid() then local l=a:K2_GetActorLocation(); local dh=math.sqrt((l.X-hl.X)^2+(l.Y-hl.Y)^2+(l.Z-hl.Z)^2); if not bd or dh<bd then best,bd=a,dh end end end; local m; for _,x in ipairs(FindAllOf('DismemberedBodySkeletalMesh_C') or {}) do if x:IsValid() and x:GetOwner()==best then m=x end end; if not m then return 'no mesh, d='..bd end; local c=m:K2_GetComponentLocation(); local cl=pc.PlayerCameraManager:GetCameraLocation(); local f={X=c.X-cl.X,Y=c.Y-cl.Y,Z=c.Z-cl.Z}; local n=math.sqrt(f.X^2+f.Y^2+f.Z^2); local e=p:K2_GetActorLocation(); e.Z=e.Z+60; local g={X=c.X-e.X,Y=c.Y-e.Y,Z=c.Z-e.Z}; local ng=math.sqrt(g.X^2+g.Y^2+g.Z^2); local P1={X=c.X+f.X/n*10,Y=c.Y+f.Y/n*10,Z=c.Z+f.Z/n*10}; local P2={X=c.X+g.X/ng*10,Y=c.Y+g.Y/ng*10,Z=c.Z+g.Z/ng*10}; local r1=p:IsInteractableInLineOfSight(best,P1,false,m,-1); local r2=p:IsInteractableInLineOfSight(best,P2,false,m,-1); local r3=p:IsInteractableInLineOfSight(best,{X=c.X,Y=c.Y,Z=c.Z},false,m,-1); local r4=p:IsInteractableInLineOfSight(best,{X=c.X,Y=c.Y,Z=c.Z+20},false,m,-1); local sel=pc:GetInteractionManager().SelectedComponent; return string.format('mode=%s d=%.0f meshd=%.0f camZ-c=%.0f eyeZ-c=%.0f fz=%.2f gz=%.2f | LOS cam+10=%s eye+10=%s center=%s up20=%s | sel=%s', tostring(p.CurrentCameraMode), bd, math.sqrt((c.X-hl.X)^2+(c.Y-hl.Y)^2), cl.Z-c.Z, e.Z-c.Z, f.Z/n, g.Z/ng, tostring(r1), tostring(r2), tostring(r3), tostring(r4), sel and sel:IsValid() and sel:GetFName():ToString() or 'nil')" 2>&1 | tail -1 | cut -c1-600
